const rows = items.map(i => i.json);
const ranked = rows.map(r => ({...r, engagement: ((r.likesCount||r.likes||0)+(r.commentsCount||r.comments||0))/Math.max(r.videoViewCount||r.views||1,1)})).sort((a,b)=>b.engagement-a.engagement);
return ranked.map(json => ({json}));

// Read-only. Skips reels that were posted, abandoned, or started too many times.
const cfg = $('Run config').first().json;
const data = $getWorkflowStaticData('global');
const attempts = data.attempts || {};
const seen = new Set([...(data.used || []), ...(data.posts || []).map(p => String(p.reelId)), ...(data.abandoned || []).map(a => String(a.reelId))]);
const idOf = i => String(i.json.id||i.json.shortCode);
const fresh = items.find(i => !seen.has(idOf(i)) && (attempts[idOf(i)] || 0) < cfg.maxReelAttempts);
if (!fresh) return [{json:{newReel:false}}];
const id = String(fresh.json.id||fresh.json.shortCode);
return [{json:{...fresh.json, newReel:true, reelId:id}}];

// A reel that keeps failing, timing out, or going unanswered is started at most
// MAX_REEL_ATTEMPTS times. After that Dedupe check stops picking it.
const data = $getWorkflowStaticData('global');
data.attempts = data.attempts || {};
const reelId = String($json.reelId);
data.attempts[reelId] = (data.attempts[reelId] || 0) + 1;
return [{ json: { ...$json, reelAttempt: data.attempts[reelId] } }];

const raw = $json.choices?.[0]?.message?.content ?? '{}';
let script;
try { script = typeof raw === 'string' ? JSON.parse(raw) : raw; }
catch (error) { throw new Error('Script step did not return JSON'); }
if (!Array.isArray(script.scenes) || script.scenes.length === 0) throw new Error('Script has no scenes');
return [{ json: { reelId: $('Dedupe check').first().json.reelId, hook: script.hook, script: script.script, voiceover: script.voiceover, caption: script.caption || script.hook, scenes: script.scenes } }];

// Runs before every paid pass: the first one, and each regeneration.
// Estimate is conservative: every pass is priced as stills + clips + voice + render.
const cfg = $('Run config').first().json;
const script = $('Parse script').last().json;
const regenTarget = $('Regeneration budget').isExecuted ? $('Regeneration budget').last().json.choice : 'first_pass';
const pass = $runIndex + 1;
const perPassUsd = script.scenes.length * (cfg.costPerStillUsd + cfg.costPerClipUsd) + cfg.costVoiceUsd + cfg.costRenderUsd;
const projectedUsd = Math.round(pass * perPassUsd * 100) / 100;
return [{ json: { ...script, pass, regenTarget, projectedUsd, costCapUsd: cfg.costCapUsd, underCap: projectedUsd <= cfg.costCapUsd + 1e-9 } }];

// Carry the submit response forward and count this poll.
const prev = $('Wait 10s — still').item.json;
return { json: { ...prev, status: $json.status, attempt: (prev.attempt || 0) + 1 } };

// Carry the submit response forward and count this poll.
const prev = $('Wait 30s').item.json;
return { json: { ...prev, status: $json.status, attempt: (prev.attempt || 0) + 1 } };

const scene = $('Scene loop').item.json;
if (!$json.video?.url) throw new Error('fal result has no video url');
return { json: { prompt: scene.prompt, narration: scene.narration, clip_url: $json.video.url } };

// Carry the submit response forward and count this poll.
const prev = $('Wait 15s — render').item.json;
return { json: { ...prev, status: $json.status, url: $json.url, attempt: (prev.attempt || 0) + 1 } };

// One run of this node per approval round, so $runIndex is the number of
// regenerations this execution has already done.
const cfg = $('Run config').first().json;
const tapped = $json.query?.choice || 'none';
const regenerationsUsed = $runIndex;
const wantsRegeneration = tapped === 'rewrite_script' || tapped === 'redo_clips';
const choice = wantsRegeneration && regenerationsUsed >= cfg.maxRegenerations ? 'cap_reached' : tapped;
return [{ json: { choice, tapped, regenerationsUsed, maxRegenerations: cfg.maxRegenerations } }];

// Rejected, or out of regenerations: record the reel so no later run picks it.
const data = $getWorkflowStaticData('global');
data.abandoned = data.abandoned || [];
const reelId = String($('Dedupe check').first().json.reelId);
const reason = $json.choice === 'reject' ? 'rejected' : 'regeneration_cap';
if (!data.abandoned.some(entry => String(entry.reelId) === reelId)) {
  data.abandoned.push({ reelId, reason, at: new Date().toISOString() });
}
return [{ json: { reelId, abandoned: true, reason, maxRegenerations: $json.maxRegenerations } }];

// Demo mode. Builds the requests a live run would send and sends none of them.
const cfg = $('Run config').first().json;
const caption = $('Parse script').last().json.caption;
const videoUrl = $('Count render poll').last().json.url;
const graph = 'https://graph.facebook.com/' + cfg.graphApiVersion;
const requests = [
  { platform: 'instagram_reels', steps: [
    { method: 'POST', url: graph + '/{ig-user-id}/media', json: { media_type: 'REELS', video_url: videoUrl, caption, share_to_feed: true } },
    { method: 'GET', url: graph + '/{container-id}', query: { fields: 'status_code' } },
    { method: 'POST', url: graph + '/{ig-user-id}/media_publish', json: { creation_id: '<id from step 1>' } } ] },
  { platform: 'tiktok', method: 'POST', url: 'https://open.tiktokapis.com/v2/post/publish/video/init/' },
  { platform: 'youtube_shorts', method: 'POST', url: 'https://www.googleapis.com/upload/youtube/v3/videos' },
];
return [{ json: { dry_run: true, sent: false, permalink: 'mock://post', requests } }];

// Carry the submit response forward and count this poll.
const prev = $('Wait 10s — container').item.json;
return { json: { ...prev, status_code: $json.status_code, attempt: (prev.attempt || 0) + 1 } };

// The only write to the used-reel list. It runs after the publish steps, so a
// failed or abandoned run leaves the reel free for a later run.
const data = $getWorkflowStaticData('global');
data.used = data.used || [];
const reelId = String($('Dedupe check').first().json.reelId);
if (!data.used.includes(reelId)) data.used.push(reelId);
return [{ json: { reelId, permalink: $json.permalink, dedupeLogged: true, usedCount: data.used.length } }];

const data = $getWorkflowStaticData('global');
data.posts = data.posts || [];
if (!data.posts.some(post => String(post.reelId) === String($json.reelId))) {
  data.posts.push({ reelId: $json.reelId, permalink: $json.permalink || 'mock://post', at: new Date().toISOString() });
}
return [{json:{logged:true, reelId: $json.reelId, posts:data.posts.length}}];
